-- Gifty backend, phase 1: the user-owned data the Android app already stores in Room.
--
-- Rows mirror the Room entities (person, occasion, gift_idea, gift). Ids are generated by the
-- Android client before it ever talks to the server, so these tables have no id defaults.
-- Android-only state (the sync queue, RemoteState) has no counterpart here: the server row is
-- the remote state.
--
-- Ownership is enforced relationally: every reference to another user-owned row is a composite
-- foreign key over (id, owner_user_id), so a row can only point at rows of the same owner, no
-- matter what RLS would let a client see. Soft deletion (deleted_at) never invalidates these
-- references; historical gifts keep pointing at deleted people and occasions.

-- Helper functions live outside the API-exposed public schema.
create schema if not exists private;

-- ---------------------------------------------------------------------------------------------
-- Types: exactly the Android enum values. Stored by name, like Room does.
-- ---------------------------------------------------------------------------------------------

create type public.occasion_type as enum ('BIRTHDAY', 'NAME_DAY', 'ANNIVERSARY', 'CHRISTMAS', 'CUSTOM');

-- A given idea is not a status: it is archived (archived_at) and referenced by its gift.
create type public.gift_idea_status as enum ('IDEA', 'PLANNED', 'PURCHASED');

-- Relative to the signed-in user, who is never stored as a person.
create type public.gift_direction as enum ('GIVEN', 'RECEIVED');

-- ISO 4217 style code. Amounts are stored separately in the currency's minor unit (bigint).
create domain public.currency_code as text
    constraint currency_code_format check (value ~ '^[A-Z]{3}$');

-- ---------------------------------------------------------------------------------------------
-- Profiles: one per auth user, created by trigger. Not part of the Android sync queue.
-- ---------------------------------------------------------------------------------------------

create table public.profiles (
    id               uuid primary key references auth.users (id) on delete cascade,
    display_name     text,
    avatar_path      text,
    preferred_locale text,
    created_at       timestamptz not null default now(),
    updated_at       timestamptz not null default now(),
    constraint profiles_display_name_not_blank check (display_name is null or btrim(display_name) <> '')
);

-- ---------------------------------------------------------------------------------------------
-- People
-- ---------------------------------------------------------------------------------------------

create table public.people (
    id             uuid primary key,
    -- Deleting an account must be designed explicitly; it never silently erases gift history.
    owner_user_id  uuid not null references auth.users (id),
    name           text not null,
    relationship   text,
    photo_path     text,
    -- Informational link to another account; it never grants access. Another user deleting
    -- their account must not be blocked by, or delete, this person.
    linked_user_id uuid references auth.users (id) on delete set null,
    version        bigint not null default 1,
    created_at     timestamptz not null default now(),
    updated_at     timestamptz not null default now(),
    deleted_at     timestamptz,
    constraint people_name_not_blank check (btrim(name) <> ''),
    constraint people_version_positive check (version >= 1),
    -- Target of the same-owner composite foreign keys below.
    constraint people_id_owner_key unique (id, owner_user_id)
);

create index people_owner_user_id_idx on public.people (owner_user_id);

-- ---------------------------------------------------------------------------------------------
-- Occasions
-- ---------------------------------------------------------------------------------------------

create table public.occasions (
    id             uuid primary key,
    owner_user_id  uuid not null references auth.users (id),
    -- Null for general occasions that belong to no particular person.
    person_id      uuid,
    type           public.occasion_type not null,
    title          text,
    day            integer not null,
    month          integer not null,
    -- Often unknown, e.g. a birthday without the birth year.
    year           integer,
    repeats_yearly boolean not null,
    version        bigint not null default 1,
    created_at     timestamptz not null default now(),
    updated_at     timestamptz not null default now(),
    deleted_at     timestamptz,
    constraint occasions_person_same_owner_fk
        foreign key (person_id, owner_user_id) references public.people (id, owner_user_id),
    -- Ranges only; the exact calendar check (e.g. 29 February) is done by the Android domain.
    constraint occasions_month_range check (month between 1 and 12),
    constraint occasions_day_range check (day between 1 and 31),
    -- The java.time.Year range the Android domain accepts, so every locally valid occasion syncs.
    constraint occasions_year_range check (year is null or year between -999999999 and 999999999),
    -- Mirrors the Android rules: custom occasions are named, and only custom occasions have a name.
    constraint occasions_custom_title_required
        check (type <> 'CUSTOM' or (title is not null and btrim(title) <> '')),
    constraint occasions_title_only_for_custom check (type = 'CUSTOM' or title is null),
    constraint occasions_always_yearly_types_repeat
        check (repeats_yearly or type not in ('BIRTHDAY', 'NAME_DAY', 'CHRISTMAS')),
    constraint occasions_one_time_needs_year check (repeats_yearly or year is not null),
    constraint occasions_version_positive check (version >= 1),
    constraint occasions_id_owner_key unique (id, owner_user_id)
);

create index occasions_owner_user_id_idx on public.occasions (owner_user_id);
create index occasions_person_id_idx on public.occasions (person_id);

-- ---------------------------------------------------------------------------------------------
-- Gift ideas
-- ---------------------------------------------------------------------------------------------

create table public.gift_ideas (
    id                            uuid primary key,
    owner_user_id                 uuid not null references auth.users (id),
    recipient_person_id           uuid not null,
    occasion_id                   uuid,
    name                          text not null,
    status                        public.gift_idea_status not null,
    estimated_price_amount_minor  bigint,
    estimated_price_currency_code public.currency_code,
    actual_price_amount_minor     bigint,
    actual_price_currency_code    public.currency_code,
    photo_path                    text,
    product_url                   text,
    note                          text,
    version                       bigint not null default 1,
    created_at                    timestamptz not null default now(),
    updated_at                    timestamptz not null default now(),
    -- Set when the idea became a gift. Not a deletion: the archived idea stays as the gift's source.
    archived_at                   timestamptz,
    deleted_at                    timestamptz,
    constraint gift_ideas_recipient_same_owner_fk
        foreign key (recipient_person_id, owner_user_id) references public.people (id, owner_user_id),
    constraint gift_ideas_occasion_same_owner_fk
        foreign key (occasion_id, owner_user_id) references public.occasions (id, owner_user_id),
    constraint gift_ideas_name_not_blank check (btrim(name) <> ''),
    constraint gift_ideas_estimated_price_pair
        check ((estimated_price_amount_minor is null) = (estimated_price_currency_code is null)),
    constraint gift_ideas_estimated_price_not_negative
        check (estimated_price_amount_minor is null or estimated_price_amount_minor >= 0),
    constraint gift_ideas_actual_price_pair
        check ((actual_price_amount_minor is null) = (actual_price_currency_code is null)),
    constraint gift_ideas_actual_price_not_negative
        check (actual_price_amount_minor is null or actual_price_amount_minor >= 0),
    constraint gift_ideas_version_positive check (version >= 1),
    constraint gift_ideas_id_owner_key unique (id, owner_user_id)
);

create index gift_ideas_owner_user_id_idx on public.gift_ideas (owner_user_id);
create index gift_ideas_recipient_person_id_idx on public.gift_ideas (recipient_person_id);
create index gift_ideas_occasion_id_idx on public.gift_ideas (occasion_id);

-- ---------------------------------------------------------------------------------------------
-- Gifts
-- ---------------------------------------------------------------------------------------------

create table public.gifts (
    id                  uuid primary key,
    owner_user_id       uuid not null references auth.users (id),
    direction           public.gift_direction not null,
    -- A null giver or recipient is the signed-in user; both set records a gift between two
    -- other people.
    giver_person_id     uuid,
    recipient_person_id uuid,
    occasion_id         uuid,
    -- The idea this gift was given from, if any.
    source_gift_idea_id uuid,
    name                text not null,
    given_at            date not null,
    price_amount_minor  bigint,
    price_currency_code public.currency_code,
    photo_path          text,
    product_url         text,
    note                text,
    version             bigint not null default 1,
    created_at          timestamptz not null default now(),
    updated_at          timestamptz not null default now(),
    deleted_at          timestamptz,
    constraint gifts_giver_same_owner_fk
        foreign key (giver_person_id, owner_user_id) references public.people (id, owner_user_id),
    constraint gifts_recipient_same_owner_fk
        foreign key (recipient_person_id, owner_user_id) references public.people (id, owner_user_id),
    constraint gifts_occasion_same_owner_fk
        foreign key (occasion_id, owner_user_id) references public.occasions (id, owner_user_id),
    constraint gifts_source_gift_idea_same_owner_fk
        foreign key (source_gift_idea_id, owner_user_id) references public.gift_ideas (id, owner_user_id),
    constraint gifts_name_not_blank check (btrim(name) <> ''),
    -- Mirrors the Android rule: a given gift says for whom, a received gift from whom.
    constraint gifts_direction_has_person check (
        (direction = 'GIVEN' and recipient_person_id is not null)
            or (direction = 'RECEIVED' and giver_person_id is not null)
    ),
    constraint gifts_price_pair check ((price_amount_minor is null) = (price_currency_code is null)),
    constraint gifts_price_not_negative check (price_amount_minor is null or price_amount_minor >= 0),
    constraint gifts_version_positive check (version >= 1)
);

create index gifts_owner_user_id_idx on public.gifts (owner_user_id);
create index gifts_giver_person_id_idx on public.gifts (giver_person_id);
create index gifts_recipient_person_id_idx on public.gifts (recipient_person_id);
create index gifts_occasion_id_idx on public.gifts (occasion_id);
-- An idea is given at most once; this also serves the source foreign key.
create unique index gifts_source_gift_idea_id_key on public.gifts (source_gift_idea_id)
    where source_gift_idea_id is not null;

-- ---------------------------------------------------------------------------------------------
-- Profile creation for new auth users
-- ---------------------------------------------------------------------------------------------

-- Runs as its owner because the signing-up user cannot write profiles directly. Kept to this one
-- insert, with an empty search_path and fully qualified names.
create function private.create_profile_for_new_user()
    returns trigger
    language plpgsql
    security definer
    set search_path = ''
as $$
begin
    insert into public.profiles (id, display_name)
    values (new.id, nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''))
    -- Safe if the trigger ever runs twice for the same user.
    on conflict (id) do nothing;
    return new;
end;
$$;

create trigger create_profile_after_signup
    after insert on auth.users
    for each row execute function private.create_profile_for_new_user();
